export const FRAMEWORK_BUTTON_COMPONENT_ID = "button";

export const FRAMEWORK_BUTTON_ARTIFACT_PATHS = Object.freeze({
  reference: "docs/generated/framework-button-slice.json",
  native: "tests/consumers/native-html/src/generated/vf-button.generated.ts",
  react: "tests/consumers/react/src/generated/Button.generated.tsx",
  angular: "tests/consumers/angular/src/app/generated/vf-button.generated.ts",
  vue: "tests/consumers/vue/src/generated/VfButton.generated.ts",
});

const GENERATED_HEADER = `/**
 * @generated by scripts/generate-framework-button-slice.mjs
 * Source: docs/metadata/component-contracts.json (component:button)
 * DO NOT EDIT. Regenerate with: npm run generate:framework-button-slice
 */`;

export class FrameworkButtonGenerationError extends Error {
  constructor(message) {
    super(message);
    this.name = "FrameworkButtonGenerationError";
  }
}

function assert(condition, message) {
  if (!condition) throw new FrameworkButtonGenerationError(message);
}

function compareText(left, right) {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

function propertyType(property) {
  const type = property.typeContract ?? {};
  let result;
  switch (type.kind) {
    case "boolean":
      result = "boolean";
      break;
    case "number":
      result = "number";
      break;
    case "bigint":
      result = "bigint";
      break;
    case "string":
      result = type.typeName ? `VyrnForge${type.typeName}` : "string";
      break;
    case "array":
      result = "readonly unknown[]";
      break;
    case "element":
      result = "Element";
      break;
    case "object":
    case "record":
      result = "Readonly<Record<string, unknown>>";
      break;
    default:
      result = "unknown";
      break;
  }
  return type.nullable === true ? `${result} | null` : result;
}

function typeImports(record) {
  return [
    ...new Set(
      record.properties
        .map((property) => property.typeContract?.typeName)
        .filter(Boolean)
        .map((name) => `VyrnForge${name}`),
    ),
  ].sort(compareText);
}

function defaultExpression(property) {
  if (property.default === undefined) return "undefined";
  return JSON.stringify(property.default);
}

function camelToKebab(value) {
  return value.replace(/[A-Z]/g, (character) => `-${character.toLowerCase()}`);
}

function assertButtonRecord(record, framework) {
  assert(record, `button: missing ${framework} generation record`);
  assert(
    record.id === FRAMEWORK_BUTTON_COMPONENT_ID,
    `${framework}: expected button record`,
  );
  if (framework === "native") {
    assert(record.tag === "vf-button", "native: Button must target vf-button");
  }
  assert(
    record.adapter.canonicalRenderer === "@vyrnforge/ui-elements",
    `${framework}: Button must keep @vyrnforge/ui-elements as canonical renderer`,
  );
  assert(
    record.properties.length > 0,
    `${framework}: Button requires generated properties`,
  );
  assert(
    record.events.some((event) => event.canonical === "vf-action"),
    `${framework}: Button requires canonical vf-action mapping`,
  );
  assert(
    record.slots.some((slot) => slot.canonical === "default"),
    `${framework}: Button requires default content mapping`,
  );
  for (const method of ["focus", "click"]) {
    assert(
      record.methods.some((entry) => entry.name === method),
      `${framework}: Button requires ${method} method mapping`,
    );
  }
  assert(
    record.accessibility.includes("native button semantics"),
    `${framework}: Button accessibility mapping must retain native button semantics`,
  );
}

export function createFrameworkButtonSliceModel(generationModel) {
  const surfaces = {};
  for (const framework of ["native", "react", "angular", "vue"]) {
    const surface = generationModel.surfaces?.[framework];
    assert(surface, `button: missing ${framework} surface`);
    const record = surface.components.find(
      (component) => component.id === FRAMEWORK_BUTTON_COMPONENT_ID,
    );
    assertButtonRecord(record, framework);
    surfaces[framework] = record;
  }

  const canonicalProperties = surfaces.native.properties
    .map((property) => property.canonical)
    .sort(compareText);
  const canonicalEvents = surfaces.native.events
    .map((event) => event.canonical)
    .sort(compareText);
  const canonicalSlots = surfaces.native.slots
    .map((slot) => slot.canonical)
    .sort(compareText);
  const canonicalMethods = surfaces.native.methods
    .map((method) => method.name)
    .sort(compareText);

  for (const framework of ["react", "angular", "vue"]) {
    assert(
      JSON.stringify(
        surfaces[framework].properties
          .map((property) => property.canonical)
          .sort(compareText),
      ) === JSON.stringify(canonicalProperties),
      `${framework}: Button property coverage diverges from Native`,
    );
    assert(
      JSON.stringify(
        surfaces[framework].events
          .map((event) => event.canonical)
          .sort(compareText),
      ) === JSON.stringify(canonicalEvents),
      `${framework}: Button event coverage diverges from Native`,
    );
    assert(
      JSON.stringify(
        surfaces[framework].slots
          .map((slot) => slot.canonical)
          .sort(compareText),
      ) === JSON.stringify(canonicalSlots),
      `${framework}: Button slot coverage diverges from Native`,
    );
    assert(
      JSON.stringify(
        surfaces[framework].methods
          .map((method) => method.name)
          .sort(compareText),
      ) === JSON.stringify(canonicalMethods),
      `${framework}: Button method coverage diverges from Native`,
    );
  }

  return {
    schemaVersion: 1,
    task: "MFD-1112",
    component: FRAMEWORK_BUTTON_COMPONENT_ID,
    canonicalRenderer: "@vyrnforge/ui-elements",
    surfaces,
  };
}

function sourceOwnership(surface) {
  return {
    package: surface.package,
    status: surface.status,
    export: surface.export,
    tag: surface.tag,
    properties: surface.properties,
    events: surface.events,
    slots: surface.slots,
    methods: surface.methods,
    accessibility: surface.accessibility,
    adapter: surface.adapter,
  };
}

export function serializeFrameworkButtonReference(model) {
  const reference = {
    schemaVersion: 1,
    generated: {
      editable: false,
      generator: "scripts/generate-framework-button-slice.mjs",
      command: "npm run generate:framework-button-slice",
      sources: ["docs/metadata/component-contracts.json"],
      sourceRecords: ["component:button"],
      task: "MFD-1112",
    },
    component: model.component,
    canonicalRenderer: model.canonicalRenderer,
    artifacts: {
      native: FRAMEWORK_BUTTON_ARTIFACT_PATHS.native,
      react: FRAMEWORK_BUTTON_ARTIFACT_PATHS.react,
      angular: FRAMEWORK_BUTTON_ARTIFACT_PATHS.angular,
      vue: FRAMEWORK_BUTTON_ARTIFACT_PATHS.vue,
    },
    surfaces: Object.fromEntries(
      ["native", "react", "angular", "vue"].map((framework) => [
        framework,
        sourceOwnership(model.surfaces[framework]),
      ]),
    ),
  };
  return `${JSON.stringify(reference, null, 2)}\n`;
}

function propertyInterfaceLines(record, indent = "  ") {
  return record.properties.map(
    (property) => `${indent}${property.public}?: ${propertyType(property)};`,
  );
}

function propertyDefaultLines(
  record,
  writer = "writeProperty",
  indent = "    ",
) {
  return record.properties.map((property) => {
    const value = defaultExpression(property);
    const publicName = property.public;
    const canonical = property.canonical;
    const resolved =
      property.default === undefined
        ? publicName
        : `${publicName} === undefined ? ${value} : ${publicName}`;
    return `${indent}${writer}(element, "${canonical}", ${resolved});`;
  });
}

function reactSource(model) {
  const record = model.surfaces.react;
  const imports = typeImports(record);
  const propertyNames = record.properties.map((property) => property.public);
  const actionEvent = record.events.find(
    (event) => event.canonical === "vf-action",
  );
  const defaultSlot = record.slots.find((slot) => slot.canonical === "default");
  const prefixSlot = record.slots.find((slot) => slot.canonical === "prefix");
  const suffixSlot = record.slots.find((slot) => slot.canonical === "suffix");
  assert(
    actionEvent?.mode === "callback",
    "react: Button vf-action must generate a callback",
  );
  assert(
    defaultSlot?.mode === "children",
    "react: Button default slot must map to children",
  );

  const destructure = [
    ...propertyNames,
    actionEvent.public,
    defaultSlot.public,
    prefixSlot?.public,
    suffixSlot?.public,
  ].filter(Boolean);
  const typeImportBlock = [
    "VyrnForgeActionDetail",
    "VyrnForgeElementForTagName",
    ...imports,
  ].sort(compareText);

  const assignments = propertyDefaultLines(record, "writeProperty", "      ");
  const dependencies = record.properties
    .map((property) => property.public)
    .join(", ");

  return `${GENERATED_HEADER}
import {
  forwardRef,
  useEffect,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
} from "react";
import type { ReactNode } from "react";
import type {
${typeImportBlock.map((name) => `  ${name},`).join("\n")}
} from "@vyrnforge/ui-elements";

export type GeneratedButtonRef = VyrnForgeElementForTagName<"vf-button">;

export interface GeneratedButtonProps {
${propertyInterfaceLines(record).join("\n")}
  ${actionEvent.public}?: (detail: VyrnForgeActionDetail) => void;
  ${defaultSlot.public}?: ReactNode;
  ${prefixSlot?.public ?? "prefix"}?: ReactNode;
  ${suffixSlot?.public ?? "suffix"}?: ReactNode;
}

function writeProperty(
  element: GeneratedButtonRef,
  name: string,
  value: unknown,
): void {
  (element as unknown as Record<string, unknown>)[name] = value;
}

export const GeneratedButton = forwardRef<GeneratedButtonRef, GeneratedButtonProps>(
  function GeneratedButton(
    {
${destructure.map((name) => `      ${name},`).join("\n")}
    },
    forwardedRef,
  ) {
    const elementRef = useRef<GeneratedButtonRef>(null);

    useImperativeHandle(
      forwardedRef,
      () => elementRef.current as GeneratedButtonRef,
      [],
    );

    useLayoutEffect(() => {
      const element = elementRef.current;
      if (!element) return;
${assignments.join("\n")}
    }, [${dependencies}]);

    useEffect(() => {
      const element = elementRef.current;
      if (!element || !${actionEvent.public}) return;
      const handleAction = (event: Event) => {
        ${actionEvent.public}((event as CustomEvent<VyrnForgeActionDetail>).detail);
      };
      element.addEventListener("vf-action", handleAction);
      return () => element.removeEventListener("vf-action", handleAction);
    }, [${actionEvent.public}]);

    return (
      <vf-button ref={elementRef} data-vf-generated-button="react">
        {${prefixSlot?.public ?? "prefix"} ? <span slot="prefix">{${prefixSlot?.public ?? "prefix"}}</span> : null}
        {${defaultSlot.public}}
        {${suffixSlot?.public ?? "suffix"} ? <span slot="suffix">{${suffixSlot?.public ?? "suffix"}}</span> : null}
      </vf-button>
    );
  },
);

GeneratedButton.displayName = "GeneratedButton";
`;
}

function angularInputLines(record, reservedPublicNames = new Set()) {
  return record.properties
    .filter((property) => !reservedPublicNames.has(property.public))
    .map((property) => {
      const internalName = `${property.public}Input`;
      return `  @Input("${property.public}")\n  set ${internalName}(value: ${propertyType(property)} | undefined) {\n    if (value !== undefined) this.writeProperty("${property.canonical}", value);\n  }`;
    })
    .join("\n\n");
}

function angularDefaultLines(record, reservedPublicNames = new Set()) {
  return record.properties
    .filter(
      (property) =>
        property.default !== undefined &&
        !reservedPublicNames.has(property.public),
    )
    .map(
      (property) =>
        `    this.writeProperty("${property.canonical}", ${defaultExpression(property)});`,
    );
}

function angularSource(model) {
  const record = model.surfaces.angular;
  const imports = typeImports(record);
  const actionEvent = record.events.find(
    (event) => event.canonical === "vf-action",
  );
  assert(
    actionEvent?.mode === "output",
    "angular: Button vf-action must generate an output",
  );

  const reservedOutputNames = new Set([actionEvent.public]);
  const typeImportBlock = [
    "VyrnForgeActionDetail",
    "VyrnForgeElementForTagName",
    ...imports,
  ].sort(compareText);

  return `${GENERATED_HEADER}
import {
  Directive,
  ElementRef,
  EventEmitter,
  Input,
  OnDestroy,
  Output,
} from "@angular/core";
import type {
${typeImportBlock.map((name) => `  ${name},`).join("\n")}
} from "@vyrnforge/ui-elements";

export type VfButtonElement = VyrnForgeElementForTagName<"vf-button">;

@Directive({
  selector: "vf-button[vfGeneratedButton]",
  standalone: true,
  exportAs: "vfButton",
})
export class VfButton implements OnDestroy {
  @Output("${actionEvent.public}")
  readonly actionOutput = new EventEmitter<VyrnForgeActionDetail>();

  // Properties that share a public name with an output remain direct host bindings.
  // This keeps both canonical mappings available without duplicate directive aliases.

  private readonly handleNativeAction = (event: Event) => {
    this.actionOutput.emit((event as CustomEvent<VyrnForgeActionDetail>).detail);
  };

  constructor(private readonly element: ElementRef<VfButtonElement>) {
${angularDefaultLines(record, reservedOutputNames).join("\n")}
    this.element.nativeElement.dataset["vfGeneratedButton"] = "angular";
    this.element.nativeElement.addEventListener("vf-action", this.handleNativeAction);
  }

${angularInputLines(record, reservedOutputNames)}

  private writeProperty(name: string, value: unknown): void {
    (this.element.nativeElement as unknown as Record<string, unknown>)[name] = value;
  }

  focus(): void {
    this.element.nativeElement.focus();
  }

  click(): void {
    this.element.nativeElement.click();
  }

  ngOnDestroy(): void {
    this.element.nativeElement.removeEventListener("vf-action", this.handleNativeAction);
  }
}
`;
}

function vuePropLines(record) {
  return record.properties.map((property) => {
    const type = propertyType(property);
    const runtimeType =
      property.typeContract?.kind === "boolean"
        ? "Boolean"
        : property.typeContract?.kind === "number"
          ? "Number"
          : "String";
    const defaultValue = defaultExpression(property);
    return `    ${property.public}: {\n      type: ${runtimeType} as PropType<${type}>,\n      default: ${defaultValue},\n    },`;
  });
}

function vueAssignmentLines(record) {
  return record.properties.map(
    (property) =>
      `      writeProperty(element, "${property.canonical}", props.${property.public});`,
  );
}

function vueSource(model) {
  const record = model.surfaces.vue;
  const imports = typeImports(record);
  const actionEvent = record.events.find(
    (event) => event.canonical === "vf-action",
  );
  const defaultSlot = record.slots.find((slot) => slot.canonical === "default");
  const prefixSlot = record.slots.find((slot) => slot.canonical === "prefix");
  const suffixSlot = record.slots.find((slot) => slot.canonical === "suffix");
  assert(
    actionEvent?.mode === "emit",
    "vue: Button vf-action must generate an emit",
  );
  assert(
    defaultSlot?.mode === "slot",
    "vue: Button default content must generate a slot",
  );

  const typeImportBlock = [
    "VyrnForgeActionDetail",
    "VyrnForgeElementForTagName",
    ...imports,
  ].sort(compareText);

  return `${GENERATED_HEADER}
import {
  defineComponent,
  h,
  onBeforeUnmount,
  onMounted,
  ref,
  watchEffect,
} from "vue";
import type { PropType } from "vue";
import type {
${typeImportBlock.map((name) => `  ${name},`).join("\n")}
} from "@vyrnforge/ui-elements";

export type VfButtonElement = VyrnForgeElementForTagName<"vf-button">;

function writeProperty(element: VfButtonElement, name: string, value: unknown): void {
  (element as unknown as Record<string, unknown>)[name] = value;
}

export const VfButton = defineComponent({
  name: "VfButton",
  inheritAttrs: false,
  props: {
    id: {
      type: String,
      default: undefined,
    },
    slot: {
      type: String,
      default: undefined,
    },
${vuePropLines(record).join("\n")}
  },
  emits: {
    "${actionEvent.public}": (_detail: VyrnForgeActionDetail) => true,
    "vf-action": (_event: Event) => true,
  },
  setup(props, { attrs, emit, expose, slots }) {
    const elementRef = ref<VfButtonElement | null>(null);

    watchEffect(() => {
      const element = elementRef.value;
      if (!element) return;
${vueAssignmentLines(record).join("\n")}
    });

    const handleAction = (event: Event) => {
      emit("${actionEvent.public}", (event as CustomEvent<VyrnForgeActionDetail>).detail);
      emit("vf-action", event);
    };

    onMounted(() => {
      elementRef.value?.addEventListener("vf-action", handleAction);
    });
    onBeforeUnmount(() => {
      elementRef.value?.removeEventListener("vf-action", handleAction);
    });

    expose({
      element: elementRef,
      focus: () => elementRef.value?.focus(),
      click: () => elementRef.value?.click(),
    });

    return () =>
      h(
        "vf-button",
        {
          ...attrs,
          id: props.id,
          slot: props.slot,
          ref: elementRef,
          "data-vf-generated-button": "vue",
        },
        [
          slots.${prefixSlot?.public ?? "prefix"}
            ? h("span", { slot: "prefix" }, slots.${prefixSlot?.public ?? "prefix"}?.())
            : null,
          slots.${defaultSlot.public}?.(),
          slots.${suffixSlot?.public ?? "suffix"}
            ? h("span", { slot: "suffix" }, slots.${suffixSlot?.public ?? "suffix"}?.())
            : null,
        ],
      );
  },
});

export default VfButton;
`;
}

function nativeSource(model) {
  const record = model.surfaces.native;
  const imports = typeImports(record);
  const actionEvent = record.events.find(
    (event) => event.canonical === "vf-action",
  );
  assert(
    actionEvent?.mode === "dom-event",
    "native: Button vf-action must remain a DOM event",
  );
  const typeImportBlock = [
    "VyrnForgeActionDetail",
    "VyrnForgeElementForTagName",
    ...imports,
  ].sort(compareText);

  const defaults = record.properties
    .filter((property) => property.default !== undefined)
    .map((property) => `  ${property.public}: ${defaultExpression(property)},`)
    .join("\n");

  return `${GENERATED_HEADER}
import type {
${typeImportBlock.map((name) => `  ${name},`).join("\n")}
} from "@vyrnforge/ui-elements";

export type GeneratedVfButtonElement = VyrnForgeElementForTagName<"vf-button">;

export interface GeneratedVfButtonOptions {
${propertyInterfaceLines(record).join("\n")}
  onAction?: (detail: VyrnForgeActionDetail) => void;
}

export const generatedVfButtonDefaults = Object.freeze({
${defaults}
});

export function bindGeneratedVfButton(
  element: GeneratedVfButtonElement,
  options: GeneratedVfButtonOptions = {},
): () => void {
  const resolved = { ...generatedVfButtonDefaults, ...options };
${record.properties
  .map(
    (property) =>
      `  (element as unknown as Record<string, unknown>)["${property.canonical}"] = resolved.${property.public};`,
  )
  .join("\n")}
  element.dataset["vfGeneratedButton"] = "native";

  const handleAction = (event: Event) => {
    options.onAction?.((event as CustomEvent<VyrnForgeActionDetail>).detail);
  };
  element.addEventListener("vf-action", handleAction);
  return () => element.removeEventListener("vf-action", handleAction);
}
`;
}

export function buildFrameworkButtonArtifacts(model) {
  return Object.freeze([
    Object.freeze({
      path: FRAMEWORK_BUTTON_ARTIFACT_PATHS.reference,
      framework: "all",
      sourceRecords: Object.freeze(["component:button"]),
      content: serializeFrameworkButtonReference(model),
    }),
    Object.freeze({
      path: FRAMEWORK_BUTTON_ARTIFACT_PATHS.native,
      framework: "native",
      sourceRecords: Object.freeze(["component:button"]),
      content: nativeSource(model),
    }),
    Object.freeze({
      path: FRAMEWORK_BUTTON_ARTIFACT_PATHS.react,
      framework: "react",
      sourceRecords: Object.freeze(["component:button"]),
      content: reactSource(model),
    }),
    Object.freeze({
      path: FRAMEWORK_BUTTON_ARTIFACT_PATHS.angular,
      framework: "angular",
      sourceRecords: Object.freeze(["component:button"]),
      content: angularSource(model),
    }),
    Object.freeze({
      path: FRAMEWORK_BUTTON_ARTIFACT_PATHS.vue,
      framework: "vue",
      sourceRecords: Object.freeze(["component:button"]),
      content: vueSource(model),
    }),
  ]);
}

export function frameworkButtonAttributeName(propertyName) {
  return camelToKebab(propertyName);
}
